48	@Configuration
49	@ConditionalOnProperty(prefix = "cache", value = "type", havingValue = "caffeine", matchIfMissing = true)
50	@EnableCaching
51	@Data
52	@Slf4j
53	public class TbCaffeineCacheConfiguration {
54	
55	    private final CacheSpecsMap configuration;
56	
57	    @Value("${cache.stats.enabled:true}")
58	    private boolean cacheStatsEnabled;
59	    @Value("${cache.stats.intervalSec:60}")
60	    private long cacheStatsInterval;
61	    @Value("${mqtt.sessions-limit:0}")
62	    private int sessionsLimit;
63	    @Value("${mqtt.application-clients-limit:0}")
64	    @Setter
65	    private int applicationClientsLimit;
66	
67	    private ScheduledExecutorService scheduler = null;
68	
69	    List<CaffeineCache> caches = Collections.emptyList();
70	
71	    @Bean
72	    public CacheManager cacheManager() {
73	        if (log.isTraceEnabled()) {
74	            log.trace("Initializing cache: {} specs {}", Arrays.toString(RemovalCause.values()), configuration.getCacheSpecs());
75	        }
76	        SimpleCacheManager manager = new SimpleCacheManager();
77	        if (configuration.getCacheSpecs() != null) {
78	            caches =
79	                    configuration.getCacheSpecs().entrySet().stream()
80	                            .map(entry -> buildCache(entry.getKey(),
81	                                    entry.getValue()))
82	                            .collect(Collectors.toList());
83	            if (sessionsLimit > 0) {
84	                caches.add(buildCache(CacheConstants.CLIENT_SESSIONS_LIMIT_CACHE, getCacheSpecsForLimitCache()));
85	            }
86	            if (applicationClientsLimit > 0) {
87	                caches.add(buildCache(CacheConstants.APP_CLIENTS_LIMIT_CACHE, getCacheSpecsForLimitCache()));
88	            }
89	            manager.setCaches(caches);
90	        }
91	
92	        //SimpleCacheManager is not a bean (will be wrapped), so call initializeCaches manually
93	        manager.initializeCaches();
94	
95	        return new TransactionAwareCacheManagerProxy(manager);
96	    }
97	
98	    @PostConstruct
99	    public void init() {
100	        if (cacheStatsEnabled) {
101	            if (log.isDebugEnabled()) {
102	                log.debug("initializing cache stats scheduled job");
103	            }
104	            scheduler = Executors.newSingleThreadScheduledExecutor(ThingsBoardThreadFactory.forName("cache-stats"));
105	            scheduler.scheduleAtFixedRate(this::printCacheStats, cacheStatsInterval, cacheStatsInterval, TimeUnit.SECONDS);
106	        }
107	    }
108	
109	    @PreDestroy
110	    public void destroy() {
111	        if (scheduler != null) {
112	            scheduler.shutdown();
113	        }
114	    }
115	
116	    void printCacheStats() {
117	        caches.forEach((cache) -> {
118	            CacheStats stats = cache.getNativeCache().stats();
119	            if (stats.hitCount() != 0 || stats.missCount() != 0) {
120	                log.info("Caffeine [{}] hit [{}] [{}]", cache.getName(), stats.hitRate(), stats);
121	            }
122	        });
123	    }
124	
125	    private CaffeineCache buildCache(String name, CacheSpecs cacheSpec) {
126	        final Caffeine<Object, Object> caffeineBuilder = Caffeine.newBuilder()
127	                .weigher(collectionSafeWeigher())
128	                .maximumWeight(cacheSpec.getMaxSize())
129	                .ticker(ticker());
130	        if (cacheSpec.getTimeToLiveInMinutes() != -1) {
131	            caffeineBuilder.expireAfterWrite(cacheSpec.getTimeToLiveInMinutes(), TimeUnit.MINUTES);
132	        }
133	        if (cacheStatsEnabled) {
134	            caffeineBuilder.recordStats();
135	        }
136	        return new CaffeineCache(name, caffeineBuilder.build());
137	    }
138	
139	    @Bean
140	    public Ticker ticker() {
141	        return Ticker.systemTicker();
142	    }
143	
144	    private Weigher<? super Object, ? super Object> collectionSafeWeigher() {
145	        return (Weigher<Object, Object>) (key, value) -> {
146	            if (value instanceof Collection) {
147	                return ((Collection) value).size();
148	            }
149	            return 1;
150	        };
151	    }
152	
153	    private CacheSpecs getCacheSpecsForLimitCache() {
154	        CacheSpecs cacheSpec = new CacheSpecs();
155	        cacheSpec.setMaxSize(1);
156	        cacheSpec.setTimeToLiveInMinutes(-1);
157	        return cacheSpec;
158	    }
159	
160	}
